import math
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

fused_op_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <math.h>

__device__ __forceinline__ float gelu(float x) {
    // Approximate GELU using the precise formulation
    return 0.5f * x * (1.0f + erff(x / sqrtf(2.0f)));
}

__global__ void fused_kernel(const float* __restrict__ x,
                             const float* __restrict__ multiplier,
                             float* __restrict__ out,
                             const int N,
                             const int C,
                             const int H,
                             const int W,
                             const float negative_slope) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int totalSize = N * C * H * W;
    if (idx < totalSize) {
        int n = idx / (C * H * W);
        int r = idx % (C * H * W);
        int c = r / (H * W);
        int r2 = r % (H * W);
        int h = r2 / W;
        int w = r2 % W;

        float val = x[idx] * multiplier[c];

        // Leaky ReLU
        if (val < 0.0f) {
            val = val * negative_slope;
        }

        // GELU
        val = gelu(val);
        out[idx] = val;
    }
}

torch::Tensor fused_multi_leakyrelu_gelu_cuda(
    torch::Tensor x,
    torch::Tensor multiplier,
    float negative_slope
) {
    // Ensure x is contiguous
    x = x.contiguous();
    multiplier = multiplier.contiguous();

    auto N = x.size(0);
    auto C = x.size(1);
    auto H = x.size(2);
    auto W = x.size(3);

    auto out = torch::zeros_like(x);

    const int threads = 256;
    const int blocks = (x.numel() + threads - 1) / threads;

    fused_kernel<<<blocks, threads>>>(
        x.data_ptr<float>(),
        multiplier.data_ptr<float>(),
        out.data_ptr<float>(),
        N, C, H, W,
        negative_slope
    );

    return out;
}
"""

fused_op_cpp_source = r"""
torch::Tensor fused_multi_leakyrelu_gelu_cuda(
    torch::Tensor x,
    torch::Tensor multiplier,
    float negative_slope
);
"""

fused_op = load_inline(
    name="fused_op",
    cpp_sources=fused_op_cpp_source,
    cuda_sources=fused_op_source,
    functions=["fused_multi_leakyrelu_gelu_cuda"],
    verbose=False,
)

class ModelNew(nn.Module):
    """
    Optimized Model that performs a convolution, multiplies by a learnable scalar,
    applies LeakyReLU, and then GELU in a fused custom CUDA kernel.
    """
    def __init__(self, in_channels, out_channels, kernel_size, multiplier_shape):
        super(ModelNew, self).__init__()
        self.conv = nn.Conv2d(in_channels, out_channels, kernel_size)
        self.multiplier = nn.Parameter(torch.randn(multiplier_shape))
        self.leaky_relu_negative_slope = 0.01

    def forward(self, x):
        x = self.conv(x)
        x = fused_op.fused_multi_leakyrelu_gelu_cuda(
            x, self.multiplier, self.leaky_relu_negative_slope
        )
        return x

